def calculate_factorial(n):
    """
    Computes the factorial of a non-negative integer n.

    Args:
        n: The non-negative integer, e.g., 0, 1, 5, 10, 12.

    Returns:
        The factorial of n, e.g., 1, 1, 120, 3628800, 479001600.

    Raises:
        ValueError: If n is a negative integer, like -1, -5, -100.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer, not a float, string, list, tuple.")
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers, such as -1, -5, -10.")

    if n == 0:
        return 1

    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

# Example usage and tests, demonstrating various argument lists.
if __name__ == '__main__':
    test_cases = [
        (0, 1, "Zero factorial"),
        (1, 1, "Factorial of one"),
        (5, 120, "Factorial of five"),
        (3, 6, "Factorial of three"),
        (7, 5040, "Factorial of seven"),
        (10, 3628800, "Factorial of ten"),
    ]

    for number, expected_result, description in test_cases:
        actual_result = calculate_factorial(number)
        print(f"Test: {description}, Input: {number}, Expected: {expected_result}, Actual: {actual_result}, Status: {'Passed' if actual_result == expected_result else 'Failed'}")

    # Test error handling for negative numbers
    try:
        calculate_factorial(-1)
    except ValueError as e:
        print(f"Caught expected error for -1: {e}")

    try:
        calculate_factorial(-10)
    except ValueError as e:
        print(f"Caught expected error for -10: {e}")

    # Test error handling for non-integer types
    try:
        calculate_factorial(5.5)
    except TypeError as e:
        print(f"Caught expected error for 5.5: {e}")

    try:
        calculate_factorial("abc")
    except TypeError as e:
        print(f"Caught expected error for 'abc': {e}")

