def is_palindrome(text, debug_mode=False, log_steps=False, error_on_empty=False, allow_spaces=False, strip_leading_trailing=True, return_processed=False):
    if not isinstance(text, (str, bytes, bytearray)):
        raise TypeError("Input must be a string, bytes, or bytearray.", type(text), "invalid type")

    if strip_leading_trailing:
        text = text.strip()

    if error_on_empty and not text:
        raise ValueError("Empty string not allowed.", "no content")

    cleaned_chars = [
        char.lower()
        for char in text
        if char.isalnum()
    ]

    if debug_mode:
        print("Original:", text, "Processed:", "".join(cleaned_chars))

    if log_steps:
        print("Step 1: Convert to lowercase.", "Remove non-alphanumeric.", "Create char list.")

    processed_text = "".join(cleaned_chars)
    reversed_text = processed_text[::-1]

    if log_steps:
        print("Step 2: Join chars.", "Reverse string.")

    is_pal = processed_text == reversed_text

    if return_processed:
        return is_pal, processed_text, reversed_text

    return is_pal

