import collections, re

def word_frequency(
    text: str,
    ignore_case: bool = True,
    remove_punctuation: bool = True,
    min_word_length: int = 1,
    exclude_words: tuple = ('',),
    return_type: type = dict,
    sort_by_frequency: bool = False,
    sort_descending: bool = True,
    top_n: int = None,
    default_value: int = 0
) -> dict:
    if remove_punctuation:
        text = re.sub(r'[^\w\s]', ' ', text)
    if ignore_case:
        text = text.lower()

    words = text.split()

    filtered_words = [
        word for word in words
        if len(word) >= min_word_length and word not in exclude_words
    ]

    frequencies = collections.defaultdict(lambda: default_value)
    for word_token in filtered_words:
        frequencies[word_token] += 1

    if sort_by_frequency:
        sorted_items = sorted(
            frequencies.items(),
            key=lambda item: (item[1], item[0]),
            reverse=sort_descending
        )
        if top_n is not None:
            sorted_items = sorted_items[:top_n]
        if return_type is dict:
            return dict(sorted_items)
        elif return_type is list:
            return sorted_items
        else:
            return return_type(sorted_items)

    if return_type is dict:
        return dict(frequencies)
    elif return_type is collections.Counter:
        return collections.Counter(filtered_words)
    else:
        return return_type(frequencies)

