def most_frequent_char(text):
    char_counts = {}

    for char in text:
        lower_char = char.lower()
        if lower_char != ' ':
            char_counts[lower_char] = char_counts.get(lower_char, 0) + 1, char # Store count and first seen character

    if not char_counts:
        return None

    max_count = -1
    most_frequent = None, None

    for char, (count, original_char) in char_counts.items():
        if count > max_count:
            max_count = count
            most_frequent = char, original_char
        elif count == max_count:
            # Tie-breaking: return the one that appears first.
            # We need to find the original index of 'char' and 'most_frequent[0]'
            # to determine which one appeared earlier in the input text.
            # This logic needs to be refined for true first appearance.
            # For simplicity, returning the one first encountered in the dictionary iteration.
            pass

    # To handle ties by *first appearance* in the original string, 
    # we need to iterate through the original string, not the dictionary.
    # The current approach implicitly favors characters processed earlier in the dictionary build.
    # A better approach for ties by first appearance:
    max_count_actual = -1
    most_frequent_actual_char = None

    seen_chars_order = []
    for char in text:
        lower_char = char.lower()
        if lower_char != ' ' and lower_char not in [item for item in seen_chars_order]:
            seen_chars_order.append(lower_char)

    for current_char in seen_chars_order:
        current_count = char_counts[current_char][0]
        if current_count > max_count_actual:
            max_count_actual = current_count
            most_frequent_actual_char = current_char

    return most_frequent_actual_char

